import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

const programs = [
  {
    title: "Weight Training",
    img: "https://images.unsplash.com/photo-1517836357463-d25dfeac3438",
    short:
      "Structured strength training focused on form, progression, and consistency.",
    long:
      "Weight Training at Bodyzeal Fitworks focuses on progressive resistance training aimed at improving strength, posture, and overall physical performance. Sessions emphasise correct movement patterns, gradual load progression, and safe training practices under trainer supervision.",
    branches: ["Nava India", "RS Puram", "Kovaipudur"],
  },
  {
    title: "Cardio Fitness",
    img: "https://images.unsplash.com/photo-1599058917212-d750089bc07e",
    short:
      "Planned cardio workouts designed to build endurance and stamina.",
    long:
      "Cardio Fitness programs are designed to improve cardiovascular endurance, stamina, and recovery using machine-based and functional training methods.",
    branches: ["Nava India", "RS Puram", "Kovaipudur"],
  },
  {
    title: "Personal Training",
    img: "https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b",
    short:
      "One-on-one coaching tailored to individual fitness goals.",
    long:
      "Personal Training offers customised workout programming with close trainer supervision. Each plan is designed around individual fitness levels, goals, and consistency.",
    branches: ["Nava India", "RS Puram", "Kovaipudur"],
  },
  {
    title: "Zumba",
    img: "https://images.unsplash.com/photo-1549576490-b0b4831ef60a",
    short:
      "Dance-based cardio sessions focused on rhythm and endurance.",
    long:
      "Zumba sessions combine dance-based movements with cardio routines to support endurance, coordination, and overall fitness.",
    branches: ["Nava India"],
  },
  {
    title: "Group Training",
    img: "https://images.unsplash.com/photo-1518611012118-696072aa579a",
    short:
      "Coach-led group workouts designed for motivation and consistency.",
    long:
      "Group Training consists of structured coach-led workouts that build strength, conditioning, and long-term consistency.",
    branches: ["Nava India"],
  },
];

export default function Programs() {
  const [active, setActive] = useState(null);

  return (
    <section
      id="programs"
      className="bg-black text-white py-32 px-6"
    >
      <div className="max-w-7xl mx-auto">

        {/* HEADING */}
        <div className="text-center max-w-3xl mx-auto mb-20">
          <h2 className="text-4xl md:text-5xl font-bold">
            Our <span className="text-red-600">Programs</span>
          </h2>
          <p className="mt-6 text-gray-400">
            Structured training programs designed to support long-term fitness.
          </p>
        </div>

        {/* PROGRAM CARDS */}
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-10">
          {programs.map((p, i) => (
            <motion.div
              key={i}
              whileHover={{ y: -6 }}
              className="relative rounded-2xl overflow-hidden border border-white/10 shadow-xl bg-black"
            >
              <img
                src={`${p.img}?auto=format&fit=crop&w=800&q=80`}
                alt={p.title}
                className="h-56 w-full object-cover"
              />

              <div className="p-6">
                <h3 className="text-xl font-semibold">{p.title}</h3>
                <p className="mt-3 text-sm text-gray-400">
                  {p.short}
                </p>

                <button
                  onClick={() => setActive(p)}
                  className="mt-5 inline-block px-5 py-2 rounded-md border border-red-600 text-red-500 hover:bg-red-600 hover:text-white transition"
                >
                  View Details
                </button>
              </div>
            </motion.div>
          ))}
        </div>
      </div>

      {/* DETAILS MODAL */}
      <AnimatePresence>
        {active && (
          <motion.div
            className="fixed inset-0 bg-black/80 backdrop-blur z-50 flex items-center justify-center px-6"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className="bg-black border border-white/10 rounded-2xl max-w-xl w-full p-8 relative"
            >
              <button
                onClick={() => setActive(null)}
                className="absolute top-4 right-4 text-gray-400 hover:text-white"
              >
                ✕
              </button>

              <h3 className="text-2xl font-bold">{active.title}</h3>
              <p className="mt-4 text-gray-300">{active.long}</p>

              <div className="mt-6">
                <h4 className="font-semibold mb-3">Available At</h4>
                <ul className="space-y-2">
                  {active.branches.map((b, i) => (
                    <li
                      key={i}
                      className="flex items-center justify-between text-sm"
                    >
                      <span>{b} Branch</span>
                      <button className="text-red-500 hover:underline">
                        View Pricing
                      </button>
                    </li>
                  ))}
                </ul>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </section>
  );
}
